vault.content:
/* eventide theme — edit me and watch the preview */
:root {
  --void: #04060c;
  --panel: #0b101d;
  --teal: #6fc2b4;
  --solar: #f2c178;
  --paper: #e9ecf1;
}

body {
  margin: 0;
  background: var(--void);
  color: var(--paper);
  font-family: monospace;
}

.card {
  background: var(--panel);
  border: 1px solid var(--teal);
  padding: 1.5rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
}

.accent { color: var(--solar); }
